{
  "name": "opencode-sound-hooks",
  "version": "1.1.3",
  "description": "OpenCode plugin for audio feedback on session events - success, error, and permission sounds",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "bin": {
    "opencode-sound-hooks": "dist/cli.js"
  },
  "type": "module",
  "files": [
    "dist",
    "assets",
    "README.md"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "sound",
    "audio",
    "notifications",
    "hooks"
  ],
  "author": "Israel Toledo",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/israeLToledo/opencode-sound-hooks"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.63",
    "@types/bun": "^1.3.9",
    "@types/node": "^22.0.0",
    "typescript": "^5.7.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  }
}
